local RegressionNewRewardCell = Class('RegressionNewRewardCell')

function RegressionNewRewardCell:__init()

end

function RegressionNewRewardCell:__delete()

end

function RegressionNewRewardCell:Awake()

end

function RegressionNewRewardCell:InitCellData(cb, data, totalCount)
	self.callBack = cb
	self.data = data
	self.totalCount = totalCount
end

function RegressionNewRewardCell:RefreshShow(curValue, isGet)
	local isCan = curValue >= self.data.rounds
	self.isCan = isCan
	self.isGet = isGet
	self:RefreshReward(isGet)
	CfUtils.FillText(self.TxtTitle, self.data.rounds)
	local state = isCan and 2 or 1
	CfUtils.SetUISwitchImage(self.ImgBgNum, state)
	
	if isCan and not isGet then
		CfUtils.SetActive(self.UIFX_RewardGlow.gameObject,true)
	else
		CfUtils.SetActive(self.UIFX_RewardGlow.gameObject,false)
	end
end

function RegressionNewRewardCell:RefreshReward(isGet)
	if not self.goodNodeMbEnv then
		---@type GoodNodeMB
		self.goodNodeMbEnv = CfUtils.GetLuaScr(self.GoodNode, Constants.UILuaTablePath.GoodNodeMB)
	end
	
	local goodsId = self.data.rewards[1].goodsId
	self.goodNodeMbEnv:Reload({
		goodsId = goodsId,
		text = string.format("x%d", self.data.rewards[1].num),
		isShowNo = true
	})
	
	self.goodNodeMbEnv:SetClickButtonAction(function()
		if self.isCan then
			self:DrawReward()
		else
			local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
			if isTable(vo) then
				GameUtils.ShowCommonTipsBoard(self.GoodNode.gameObject, vo.name, vo.desc, vo.quality, vo.id)
			end
		end
	end)
	
	self.goodNodeMbEnv:SetSanXingGainShow(isGet)
end

function RegressionNewRewardCell:DrawReward()
	if self.callBack then
		self.callBack()
	end
end

function RegressionNewRewardCell:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return RegressionNewRewardCell